"""Write rtl/itch_hash_pkg.vhd: the order table's H3 masks, from itch/hashing.py.

    python3.11 scripts/gen_hash_pkg.py -o rtl/itch_hash_pkg.vhd

The model and the hardware must use the same masks, so the VHDL package is generated, never
edited by hand.
"""

import argparse
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from itch.hashing import HASH_BITS, HASH_SEEDS, HASHES  # noqa: E402


def vhdl_package() -> str:
    lines = [
        "-- Generated by scripts/gen_hash_pkg.py from itch/hashing.py. Do not edit.",
        f"-- H3 hash masks, seeds 0x{HASH_SEEDS[0]:X} and 0x{HASH_SEEDS[1]:X}: bucket bit i of table t is",
        "-- XOR (order_ref AND H3_MASK_t(i)), over the full 64-bit order ref.",
        "",
        "LIBRARY ieee;",
        "USE ieee.std_logic_1164.ALL;",
        "",
        "PACKAGE itch_hash_pkg IS",
        "",
        f"    TYPE MASK_ARRAY_T IS ARRAY (0 TO {HASH_BITS - 1}) OF STD_LOGIC_VECTOR(63 DOWNTO 0);",
    ]
    for table, hash_function in enumerate(HASHES):
        lines.append("")
        lines.append(f"    CONSTANT H3_MASK_{table} : MASK_ARRAY_T := (")
        masks = [f'        x"{mask:016X}"' for mask in hash_function.masks]
        lines.append(",\n".join(masks))
        lines.append("    );")
    lines += ["", "END PACKAGE;", ""]
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("-o", "--output", type=Path, required=True)
    args = parser.parse_args()
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(vhdl_package())
    print(f"wrote {args.output}")


if __name__ == "__main__":
    main()
